-- =============================================================================================
-- Hand-written below this line: department names unique among active ones, archiving final and
-- only without upcoming shifts; members of active departments only, once at a time, removed
-- once; shifts of 15 minutes to 24 hours for a current member, never overlapping for a person
-- (advisory lock per person), moving only SCHEDULED -> STARTED -> ENDED (handover note
-- required) or SCHEDULED -> CANCELLED (reason required), times set by the database.
-- See docs/architecture/DATA_MODEL.md section 10 (Staff operations).
-- =============================================================================================

ALTER TABLE "departments" ADD CONSTRAINT "departments_text"
  CHECK ("name" = btrim("name") AND length("name") BETWEEN 1 AND 80);
ALTER TABLE "departments" ADD CONSTRAINT "departments_archived"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));
CREATE UNIQUE INDEX "departments_active_name_key" ON "departments" ("property_id", lower("name"))
  WHERE "status" = 'ACTIVE';

CREATE FUNCTION app_department_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'ACTIVE' THEN
      RAISE EXCEPTION 'departments start active' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    NEW."archived_at" := NULL;
    RETURN NEW;
  END IF;
  IF OLD."status" = 'ARCHIVED' THEN
    RAISE EXCEPTION 'department % is archived and no longer changes', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."created_at") THEN
    RAISE EXCEPTION 'department % stays at its property', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  NEW."archived_at" := OLD."archived_at";
  IF NEW."status" = 'ARCHIVED' THEN
    IF EXISTS (SELECT 1 FROM "shifts" WHERE "department_id" = OLD."id" AND "status" IN ('SCHEDULED', 'STARTED')) THEN
      RAISE EXCEPTION 'cancel or finish the shifts of this department before archiving it' USING ERRCODE = 'check_violation';
    END IF;
    NEW."archived_at" := now();
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "departments_guard"
  BEFORE INSERT OR UPDATE ON "departments"
  FOR EACH ROW EXECUTE FUNCTION app_department_guard();

CREATE UNIQUE INDEX "department_members_current_key" ON "department_members" ("department_id", "user_id")
  WHERE "removed_at" IS NULL;

CREATE FUNCTION app_department_member_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM "departments" WHERE "id" = NEW."department_id" AND "status" = 'ACTIVE') THEN
      RAISE EXCEPTION 'the department is archived' USING ERRCODE = 'check_violation';
    END IF;
    NEW."added_at" := now();
    NEW."removed_at" := NULL;
    RETURN NEW;
  END IF;
  IF OLD."removed_at" IS NOT NULL OR NEW."removed_at" IS NULL
     OR (NEW."organisation_id", NEW."property_id", NEW."department_id", NEW."user_id", NEW."added_at")
        IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."department_id", OLD."user_id", OLD."added_at") THEN
    RAISE EXCEPTION 'a department member is removed once, and nothing else changes' USING ERRCODE = 'check_violation';
  END IF;
  NEW."removed_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "department_members_guard"
  BEFORE INSERT OR UPDATE ON "department_members"
  FOR EACH ROW EXECUTE FUNCTION app_department_member_guard();

ALTER TABLE "shifts" ADD CONSTRAINT "shifts_length"
  CHECK ("ends_at" >= "starts_at" + interval '15 minutes' AND "ends_at" <= "starts_at" + interval '24 hours');
ALTER TABLE "shifts" ADD CONSTRAINT "shifts_text"
  CHECK (("handover_note" IS NULL OR ("handover_note" = btrim("handover_note") AND length("handover_note") BETWEEN 1 AND 4000))
         AND ("cancel_reason" IS NULL OR ("cancel_reason" = btrim("cancel_reason") AND length("cancel_reason") BETWEEN 1 AND 1000)));
ALTER TABLE "shifts" ADD CONSTRAINT "shifts_status"
  CHECK (("status" IN ('STARTED', 'ENDED')) = ("started_at" IS NOT NULL)
         AND ("status" = 'ENDED') = ("ended_at" IS NOT NULL)
         AND ("status" = 'ENDED') = ("handover_note" IS NOT NULL)
         AND ("status" = 'CANCELLED') = ("cancel_reason" IS NOT NULL));

CREATE FUNCTION app_shift_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  transition text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'SCHEDULED' THEN
      RAISE EXCEPTION 'shifts start scheduled' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "departments" WHERE "id" = NEW."department_id" AND "status" = 'ACTIVE') THEN
      RAISE EXCEPTION 'the department is archived' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "department_members" WHERE "department_id" = NEW."department_id"
                      AND "user_id" = NEW."user_id" AND "removed_at" IS NULL) THEN
      RAISE EXCEPTION 'shifts go to members of the department' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    NEW."started_at" := NULL;
    NEW."ended_at" := NULL;
    NEW."handover_note" := NULL;
    NEW."cancel_reason" := NULL;
  ELSE
    IF OLD."status" IN ('ENDED', 'CANCELLED') THEN
      RAISE EXCEPTION 'shift % is % and no longer changes', OLD."id", lower(OLD."status"::text)
        USING ERRCODE = 'check_violation';
    END IF;
    IF (NEW."organisation_id", NEW."property_id", NEW."department_id", NEW."user_id", NEW."created_by_user_id", NEW."created_at")
       IS DISTINCT FROM
       (OLD."organisation_id", OLD."property_id", OLD."department_id", OLD."user_id", OLD."created_by_user_id", OLD."created_at") THEN
      RAISE EXCEPTION 'shift % keeps its department and person', OLD."id" USING ERRCODE = 'check_violation';
    END IF;
    IF OLD."status" <> 'SCHEDULED' AND (NEW."starts_at", NEW."ends_at") IS DISTINCT FROM (OLD."starts_at", OLD."ends_at") THEN
      RAISE EXCEPTION 'a shift is rescheduled only before it starts' USING ERRCODE = 'check_violation';
    END IF;
    NEW."started_at" := OLD."started_at";
    NEW."ended_at" := OLD."ended_at";
    IF NEW."status" = OLD."status" THEN
      NEW."handover_note" := OLD."handover_note";
      NEW."cancel_reason" := OLD."cancel_reason";
    ELSE
      transition := OLD."status" || '>' || NEW."status";
      IF transition NOT IN ('SCHEDULED>STARTED', 'SCHEDULED>CANCELLED', 'STARTED>ENDED') THEN
        RAISE EXCEPTION 'a shift cannot go from % to %', lower(OLD."status"::text), lower(NEW."status"::text)
          USING ERRCODE = 'check_violation';
      END IF;
      IF NEW."status" = 'ENDED' AND NEW."handover_note" IS NULL THEN
        RAISE EXCEPTION 'write a handover note to end the shift' USING ERRCODE = 'check_violation';
      END IF;
      IF NEW."status" = 'CANCELLED' AND NEW."cancel_reason" IS NULL THEN
        RAISE EXCEPTION 'give a reason to cancel the shift' USING ERRCODE = 'check_violation';
      END IF;
      IF NEW."status" <> 'ENDED' THEN NEW."handover_note" := NULL; END IF;
      IF NEW."status" <> 'CANCELLED' THEN NEW."cancel_reason" := NULL; END IF;
      IF NEW."status" = 'STARTED' THEN NEW."started_at" := now(); END IF;
      IF NEW."status" = 'ENDED' THEN NEW."ended_at" := now(); END IF;
    END IF;
  END IF;
  -- A person's live shifts never overlap.
  IF NEW."status" IN ('SCHEDULED', 'STARTED') THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('veyra.shifts:' || NEW."user_id"::text, 0));
    IF EXISTS (SELECT 1 FROM "shifts" WHERE "user_id" = NEW."user_id" AND "id" <> NEW."id"
                  AND "status" IN ('SCHEDULED', 'STARTED')
                  AND "starts_at" < NEW."ends_at" AND "ends_at" > NEW."starts_at") THEN
      RAISE EXCEPTION 'this person already has a shift then' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "shifts_guard"
  BEFORE INSERT OR UPDATE ON "shifts"
  FOR EACH ROW EXECUTE FUNCTION app_shift_guard();

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['departments', 'department_members', 'shifts'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "departments", "department_members", "shifts" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "departments", "department_members", "shifts" TO veyra_app;
